class Codec {
public:
    TreeNode* encode(Node* root) {
        if (!root) {
            return nullptr;
        }
        TreeNode* node = new TreeNode(root->val);
        TreeNode* previous = nullptr;
        for (Node* child : root->children) {
            TreeNode* encoded = encode(child);
            if (!previous) {
                node->left = encoded;
            } else {
                previous->right = encoded;
            }
            previous = encoded;
        }
        return node;
    }

    Node* decode(TreeNode* root) {
        if (!root) {
            return nullptr;
        }
        Node* node = new Node(root->val);
        for (TreeNode* child = root->left; child; child = child->right) {
            node->children.push_back(decode(child));
        }
        return node;
    }
};
